"""Build 3 revised notebooks for the binary XGBoost + scale_pos_weight + TreeSHAP plan.
NOTE 2026-11-18: model final pindah ke scale_pos_weight — lihat notebooks/03_xgboost_smotenc_shap.ipynb
(yang sudah diedit langsung) sebagai sumber kebenaran; builder ini belum sepenuhnya disinkronkan untuk final fit SPW.
Run:  python build_revised_notebooks.py
Output: notebooks/revised/01_..., 02_..., 03_...
Old 03/04/05 are archived in notebooks/archive/ — their NUMBERS are kept
as baseline in notebook 03, they are not re-run.
"""
import json
from pathlib import Path

OUT = Path(__file__).parent / "notebooks" / "revised"
OUT.mkdir(parents=True, exist_ok=True)

def md(src):
    return {"cell_type": "markdown", "metadata": {}, "source": src.splitlines(True)}
def code(src):
    return {"cell_type": "code", "execution_count": None, "metadata": {}, "outputs": [], "source": src.splitlines(True)}
def nb(cells):
    return {"cells": cells, "metadata": {"kernelspec": {"display_name": "Python 3 (ml-inventaris)", "language": "python", "name": "python3"}, "language_info": {"name": "python", "version": "3.11.0"}}, "nbformat": 4, "nbformat_minor": 5}
def save(name, cells):
    (OUT / name).write_text(json.dumps(nb(cells), indent=1, ensure_ascii=False), encoding="utf-8")
    print("wrote", name, len(cells), "cells")

# ================= 01 =================
