cells02 = [
md("# 02 — Preprocessing (REVISI)\n\n**Yang dipertahankan dari skripsi:** duplikat exact 21 dibuang / logis 139 dipertahankan, outlier IQR dideteksi tapi dipertahankan, imputasi hierarkis, rumus depresiasi domain-informed.\n\n**Yang DIPERBAIKI di revisi ini:**\n1. Path relatif (`../data/raw/...`), bukan `/Skripsi/...` atau `D:/Skripsi/...`.\n2. `REFERENCE_YEAR = 2025` (data triwulan 2025), bukan hardcode 2026 — umur barang 2025 jadi 0, bukan 1. Untuk data baru di aplikasi, umur dihitung dinamis dari tahun berjalan.\n3. **Imputasi TIDAK lagi dihitung di full data lalu dipakai begitu saja.** Notebook ini menyimpan DUA file:\n   - `inventaris_processed.csv` — versi ter-imputasi, untuk EDA/dashboard (praktis).\n   - `inventaris_for_model.csv` — versi `harga_per_unit`/`depresiasi_aset` masih NaN, untuk training di notebook 03 di mana imputasi dihitung HANYA dari train tiap fold (tanpa leakage).\n4. `preprocessing_reference.pkl` diperbaiki: menyimpan mean `harga_per_unit` (bukan `harga` total), median, dan masa manfaat.\n5. Target biner dibuat di sini, tapi `kondisi_asli` tetap disimpan untuk audit. Metadata `nama_barang`, `nama_ruangan`, `triwulan` tetap disimpan (bukan fitur model, tapi perlu untuk dashboard)."),
code("import pandas as pd\nimport numpy as np\nimport joblib\nfrom pathlib import Path\n\npd.options.display.float_format = '{:.2f}'.format\nREFERENCE_YEAR = 2025  # data triwulan 2025; JANGAN 2026\nRAW = Path('../data/raw/inventaris_raw.csv')\nPROC = Path('../data/processed')\nPROC.mkdir(parents=True, exist_ok=True)\ndf = pd.read_csv(RAW)\nprint('awal:', len(df))"),
code("# --- Cleaning: strip + buang duplikat EXACT saja ---\nfor col in ['bahan','kategori','kondisi','nama_ruangan']:\n    df[col] = df[col].astype(str).str.strip()\nprint('duplikat exact:', int(df.duplicated().sum()))\nsubset = ['triwulan','nama_ruangan','nama_barang','tahun_pembelian']\nprint('duplikat logis (subset di atas, DIPERTAHANKAN karena batch stok beda):', int(df.duplicated(subset=subset).sum()))\ndf = df.drop_duplicates().copy()\nprint('setelah cleaning:', len(df), '(harus 2301)')"),
code("# --- Outlier IQR: deteksi saja, TIDAK dibuang ---\nfor col in ['tahun_pembelian','jumlah','harga']:\n    q1, q3 = df[col].quantile(0.25), df[col].quantile(0.75)\n    iqr = q3-q1\n    n = int(((df[col] < q1-1.5*iqr) | (df[col] > q3+1.5*iqr)).sum())\n    print(f'{col}: {n} outlier ({n/len(df)*100:.2f}%) — dipertahankan (kondisi nyata)')"),
code("# --- Feature engineering ---\ndf['umur'] = REFERENCE_YEAR - df['tahun_pembelian']\ndf['harga_per_unit'] = df['harga'] / df['jumlah']\nprint('missing harga_per_unit sebelum imputasi:', int(df['harga_per_unit'].isna().sum()), '(harus ~1289)')\nprint(df[['umur','harga_per_unit']].describe().T)"),
code("def depresiasi_row(row):\n    umur, harga = row['umur'], row['harga_per_unit']\n    if pd.isna(harga):\n        return np.nan\n    if row['kategori'] == 'Elektronik':\n        nilai_buku = harga\n        for _ in range(int(umur)):\n            nilai_buku -= nilai_buku * (2/5)\n        dep = harga - nilai_buku\n    else:\n        dep = (harga/10) * umur\n    return round(min(dep, harga), 2)\n\ndf['depresiasi_aset'] = df.apply(depresiasi_row, axis=1)\nprint('depresiasi: min/median/max =', df['depresiasi_aset'].min(), df['depresiasi_aset'].median(), df['depresiasi_aset'].max())"),
code("# --- Target biner + simpan kondisi asli ---\ndf['kondisi_asli'] = df['kondisi']\ndf['kondisi_biner'] = df['kondisi'].map({'Baik': 0, 'Kurang Baik': 1, 'Rusak Berat': 1})\nprint(df['kondisi_biner'].value_counts().to_dict())\nassert df['kondisi_biner'].isna().sum() == 0"),
code("# --- Simpan VERSI UNTUK MODEL (NaN dipertahankan, imputasi nanti di dalam fold notebook 03) ---\ncols_model = ['triwulan','nama_ruangan','nama_barang','bahan','kategori','umur','harga_per_unit','depresiasi_aset','kondisi_asli','kondisi_biner']\ndf_model = df[cols_model].copy()\ndf_model.to_csv(PROC/'inventaris_for_model.csv', index=False)\nprint('saved inventaris_for_model.csv:', df_model.shape, '| NaN harga_per_unit:', int(df_model['harga_per_unit'].isna().sum()))"),
code("# --- Imputasi hierarkis HANYA untuk file EDA/dashboard (dan untuk referensi nilai) ---\n# Urutan: mean per nama_barang -> mean per bahan+kategori -> median. Nilai-nilai ini\n# disimpan ke reference.pkl dan DIPAKAI KEMBALI di notebook 03 / FastAPI untuk data baru.\ndf_imp = df.copy()\ndf_imp['harga_per_unit'] = df_imp.groupby('nama_barang')['harga_per_unit'].transform(lambda x: x.fillna(x.mean()))\ndf_imp['harga_per_unit'] = df_imp.groupby(['bahan','kategori'])['harga_per_unit'].transform(lambda x: x.fillna(x.mean()))\ndf_imp['harga_per_unit'] = df_imp['harga_per_unit'].fillna(df_imp['harga_per_unit'].median())\ndf_imp['depresiasi_aset'] = df_imp.apply(depresiasi_row, axis=1)\nprint('missing setelah imputasi (versi EDA):', int(df_imp['harga_per_unit'].isna().sum()))\ncols_proc = ['bahan','kategori','umur','harga_per_unit','depresiasi_aset','kondisi_asli','kondisi_biner']\ndf_imp[cols_proc].to_csv(PROC/'inventaris_processed.csv', index=False)\nprint('saved inventaris_processed.csv:', df_imp[cols_proc].shape)"),
code("# --- Reference v2 (DIPERBAIKI: pakai harga_per_unit, bukan harga total) ---\nreference = {\n    'reference_year': REFERENCE_YEAR,\n    'median_harga_per_unit': float(df['harga_per_unit'].median()),\n    'harga_per_unit_nama_mean': df.groupby('nama_barang')['harga_per_unit'].mean().to_dict(),\n    'harga_per_unit_group_mean': df.groupby(['bahan','kategori'])['harga_per_unit'].mean().to_dict(),\n    'bahan_mapping': df.groupby('nama_barang')['bahan'].agg(lambda x: x.mode().iloc[0]).to_dict(),\n    'kategori_mapping': df.groupby('nama_barang')['kategori'].agg(lambda x: x.mode().iloc[0]).to_dict(),\n    'masa_manfaat': {'Elektronik': 5, 'Furnitur': 10, 'Pelengkap': 10},\n    'depresiasi_method': {'Elektronik': 'double_declining', 'Furnitur': 'straight_line', 'Pelengkap': 'straight_line'},\n}\njoblib.dump(reference, '../models/preprocessing_reference_v2.pkl')\nprint('saved preprocessing_reference_v2.pkl')\nprint('statistik akhir (versi ter-imputasi):')\ndisplay(df_imp[['umur','harga_per_unit','depresiasi_aset']].describe().T)"),
md("## Kesimpulan 02\n\n- File model: `data/processed/inventaris_for_model.csv` (2.301 baris, NaN dipertahankan) → dipakai notebook 03.\n- File EDA: `data/processed/inventaris_processed.csv` (ter-imputasi) → dipakai dashboard.\n- Jangan pernah pakai file EDA untuk klaim evaluasi tanpa leakage — evaluasi yang benar ada di notebook 03, di mana imputasi/scaler/encoder/SMOTE-NC semuanya di-fit HANYA di train tiap fold.\n\nLanjut ke `03_xgboost_smotenc_shap.ipynb`."),
]
